// Mod 1: WATCH. Count every tool Claude uses, and answer /tally with the count.
let calls = 0

export function register(on) {
  // When a session starts, tell Claude Code that /tally exists
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'tally', description: 'Show how many tool calls Claude has made' })
    return next(e)
  })

  // Every tool call passes through here. Count it, then pass it on untouched.
  on('tool.call', async ($, e, next) => {
    calls += 1
    $.ui.invalidate('ui.render')
    return next(e)
  })

  // /tally is answered by this function. No model is asked, so it costs nothing.
  on('command.run', { command: 'tally' }, async () => {
    return { text: 'Claude has made ' + calls + ' tool calls since this mod loaded' }
  })

  // Put the count after the spinner's word while Claude works
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    if (calls === 0) return next(e)
    return next({ ...e, props: { ...e.props, suffix: ' · tool calls: ' + calls + '…' } })
  })
}

